 $il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$output);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$position);$il.Emit([Reflection.Emit.OpCodes]::Callvirt,[string].GetProperty('Chars').GetMethod)
 $il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$position);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Add);$il.Emit([Reflection.Emit.OpCodes]::Stfld,$position);$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($m,$buffer.GetMethod('GetNextChar'))
