 $builder=$module.DefineType('Custom'+$Direction+'Fallback',[Reflection.TypeAttributes]::Public,$base);[void]$builder.DefineDefaultConstructor([Reflection.MethodAttributes]::Public);$text=$builder.DefineField('Replacement',[string],[Reflection.FieldAttributes]::Public);$maximum=$builder.DefineField('Maximum',[int],[Reflection.FieldAttributes]::Public);$mode=$builder.DefineField('Mode',[int],[Reflection.FieldAttributes]::Public);$calls=$builder.DefineField('FactoryCalls',[int],[Reflection.FieldAttributes]::Public)
