$bufferTypes=@{};$decoderType=CustomType 'Decoder';$bufferType=$bufferTypes.Decoder
function RawBuffer($decoder){return [Text.Decoder].GetProperty('FallbackBuffer').GetMethod.Invoke($decoder,[object[]]@())}
function RequiredBuffer($decoder){$buffer=RawBuffer $decoder;if($null -eq $buffer){throw [NullReferenceException]::new()};return $buffer}
function A([string]$op,[int[]]$units=@(),[bool]$flush=$true,[int]$capacity=8){return [ordered]@{operation=$op;units=$units;flush=$flush;capacity=$capacity}}
$bridges=@{};$argsTypes=[type[]]@([Text.Decoder],[byte[]],[int],[int],[char[]],[int],[int],[bool],[int[]],[bool[]]);$nativeArgs=[type[]]@([byte[]],[int],[int],[char[]],[int],[int],[bool],[int].MakeByRefType(),[int].MakeByRefType(),[bool].MakeByRefType());$method=[Text.Decoder].GetMethod('Convert',$nativeArgs);foreach($alias in @($false,$true)){$bridge=[Reflection.Emit.DynamicMethod]::new(('DecoderConvertBoundary'+$alias),[void],$argsTypes);$il=$bridge.GetILGenerator();foreach($i in 0..7){$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]$i)};foreach($index in 0..1){$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]8);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,$(if($alias){0}else{$index}));$il.Emit([Reflection.Emit.OpCodes]::Ldelema,[int])};$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]9);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ldelema,[bool]);$il.Emit([Reflection.Emit.OpCodes]::Callvirt,$method);$il.Emit([Reflection.Emit.OpCodes]::Ret);$action=[type]'System.Action`10';$bridges[[string]$alias]=$bridge.CreateDelegate($action.MakeGenericType($argsTypes))}
$convertBridge=$bridges['False']
$sequences=@(
 @((A C @(255) $true 0),(A C @(255) $true 1),(A C @(255) $true 2),(A C @(255) $true 4),(A C @(65)),(A Reset)),
 @((A C @(226) $false 0),(A C @(130,172) $false 4),(A C @() $true 0),(A Reset)),
 @((A C @(226) $false 0),(A C @() $true 1),(A Count @(65)),(A Chars @(65)),(A Remaining),(A Reset),(A C @(255))),
 @((A C @(65,255) $true 2),(A C @() $true 1),(A Count @(65)),(A Chars @(65)),(A Replace),(A C @(255)),(A Reset)),
 @((A Buffer),(A Fill),(A C @(65) $true 1),(A Count @(65)),(A Chars @(65)),(A Reset)),
 @((A C @(255) $true 1),(A Null),(A Replace),(A C @(255) $true 2),(A C @(255)),(A Reset)),
 @((A C @(255) $true 4),(A C @(65) $true 0),(A C @() $true 0),(A Reset))
