foreach($template in 0..3){foreach($mode in 0..10){$rows=@();$provider=[Activator]::CreateInstance($decoderType);$decoderType.GetField('Replacement').SetValue($provider,[string]::new([char[]][int[]]$templates[$template]));$decoderType.GetField('Maximum').SetValue($provider,10);$decoderType.GetField('Mode').SetValue($provider,$mode);$encoding=[Text.Encoding]([Text.UTF8Encoding]::new()).Clone();$encoding.DecoderFallback=$provider
 foreach($sequenceId in 0..($sequences.Count-1)){$decoder=$encoding.GetDecoder();$steps=@();foreach($action in $sequences[$sequenceId]){$decoderType.GetField('FactoryCalls').SetValue($provider,0);foreach($name in @('NextCalls','FallbackCalls','RemainingCalls','MoveCalls','ResetCalls')){$bufferType.GetField($name).SetValue($null,0)};$destination=$null;$used=[int[]]@(-7,-8);$completed=[bool[]]@($true)
  try{switch($action.operation){
   'C'{$chars=[byte[]][int[]]$action.units;$destination=[char[]]::new([int]$action.capacity);[Array]::Fill[char]($destination,[char]99);$arguments=[object[]]::new(10);$arguments[0]=[Text.Decoder]$decoder;$arguments[1]=[byte[]]$chars;$arguments[2]=[int]0;$arguments[3]=[int]$chars.Length;$arguments[4]=[char[]]$destination;$arguments[5]=[int]0;$arguments[6]=[int]$action.capacity;$arguments[7]=[bool]$action.flush;$arguments[8]=$used;$arguments[9]=$completed;$convertBridge.DynamicInvoke($arguments)|Out-Null;$result=[ordered]@{ok=$true;count=0}}
   'Count'{$chars=[byte[]][int[]]$action.units;$result=[ordered]@{ok=$true;count=$decoder.GetCharCount($chars,0,$chars.Length,[bool]$action.flush)}}
   'Chars'{$chars=[byte[]][int[]]$action.units;$destination=[char[]]::new([int]$action.capacity);[Array]::Fill[char]($destination,[char]99);$result=[ordered]@{ok=$true;count=$decoder.GetChars($chars,0,$chars.Length,$destination,0,[bool]$action.flush)}}
