  }}catch{$e=$_.Exception;while(($e -is [Management.Automation.RuntimeException] -or $e -is [Reflection.TargetInvocationException]) -and $null -ne $e.InnerException){$e=$e.InnerException};$result=[ordered]@{ok=$false;exception=$e.GetType().FullName;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
  $steps+=@([ordered]@{action=$action;result=$result;used=[int[]]$used;completed=$completed[0];factoryCalls=$decoderType.GetField('FactoryCalls').GetValue($provider);bufferCalls=@(foreach($name in @('NextCalls','FallbackCalls','RemainingCalls','MoveCalls','ResetCalls')){[int]$bufferType.GetField($name).GetValue($null)});after=$(if($null -eq $destination){$null}else{,[int[]]$destination})})
 };$rows+=@([ordered]@{sequence=$sequenceId;steps=$steps})}
