}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();profiles=$profiles;outCapture='DIRECT_IL_BYREF_ADDRESSES_IN_SENTINEL_INITIALIZED_ARRAYS';qualification='SELECTED_CUSTOM_DECODER_CONVERT_REFERENCE_ONLY; ARBITRARY_REENTRANCY_BASE_DECODER_SPAN_POINTER_FULL_METADATA_SOURCE_ABI_AND_TASK_ACCEPTANCE_OPEN'}
